public_reexports:
ports::{
    AuthTransport, Clock, HttpMethod, RandomSource, TransportFuture, TransportRequest,
    TransportResponse,
}

steps.run:
cargo metadata --locked --no-deps --format-version 1 > /tmp/package-metadata.json
node --input-type=module <<'JS'
import fs from 'node:fs';
const d = JSON.parse(fs.readFileSync('/tmp/package-metadata.json'));
const p = d.packages.find(p => p.manifest_path === `${process.env.GITHUB_WORKSPACE}/Cargo.toml`);
if (!p || JSON.stringify(p.publish) !== '["crates-io"]'
  || p.repository !== `https://github.com/${process.env.GITHUB_REPOSITORY}`) {
  throw new Error('Public package metadata is not the reviewed crate');
}
fs.appendFileSync(process.env.GITHUB_ENV, `PACKAGE_ARCHIVE=target/package/${p.name}-${p.version}.crate\n`);
fs.appendFileSync(process.env.GITHUB_OUTPUT, `version=${p.version}\n`);
JS
